using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|KeyValue" to just "KeyValue".
            // Existing documents use "Blog|1" format, so we set IdProperty to keep reading them.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id");

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core in the same way.
            // HasIndex is now unsupported for Cosmos provider in EF 9 — removed.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

